import { 
  Mesh, 
  PlaneGeometry, 
  Group,
  Color,
  DoubleSide
} from 'three/webgpu';
import { 
  texture, 
  uv, 
  vec2, 
  vec3, 
  vec4,
  mix,
  float,
  sub,
  add,
  mul,
  hash,
  Fn
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Design palette
  const palette = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // Atlas region
  const atlasRect = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;

  // Plane size
  const w = 1.6;
  const h = w / aspect;

  const geo = new PlaneGeometry(w, h);

  // Load texture
  const metalTex = ctx.textureLoader(config.assets.imageUrl);

  // UV adjustment for atlas region
  const texW = (metalTex.image && metalTex.image.width) || atlasRect.w;
  const texH = (metalTex.image && metalTex.image.height) || atlasRect.h;
  const sx = atlasRect.w / texW;
  const sy = atlasRect.h / texH;
  const ox = atlasRect.x / texW;
  const oy = 1.0 - (atlasRect.y + atlasRect.h) / texH; // flip Y for Three.js

  // Build TSL material
  const mat = new MeshBasicNodeMaterial();
  mat.side = DoubleSide;
  mat.transparent = true;

  // Texture node with atlas UV
  const texNode = texture(metalTex);
  const atlasUV = uv().mul(vec2(sx, sy)).add(vec2(ox, oy));
  const sampled = texNode.uv(atlasUV);

  // Engineered gradient overlay (surface to ink, top to bottom)
  const gradientFactor = uv().y; // 0 at bottom, 1 at top
  const gradientColor = mix(
    vec3(palette.surface.r, palette.surface.g, palette.surface.b),
    vec3(palette.ink.r, palette.ink.g, palette.ink.b),
    gradientFactor
  );

  // Blend texture with gradient
  const blended = mix(sampled.rgb(), gradientColor, float(0.35));

  // Subtle grain
  const grainUV = uv().mul(vec2(128.0, 80.0));
  const grain = hash(grainUV).sub(float(0.5)).mul(float(0.04));
  const finalColor = blended.add(grain);

  mat.colorNode = vec4(finalColor, float(1.0));

  const plane = new Mesh(geo, mat);
  group.add(plane);

  // Text via fontAtlas
  if (config.textContent) {
    const textStr = typeof config.textContent === 'string' 
      ? config.textContent 
      : config.textContent.text || 'Journal 1';

    const textMesh = ctx.fontAtlas({
      text: textStr,
      font: 'lora',
      weight: 400,
      size: 0.2,
      color: palette.paper,
      align: 'center',
      letterSpacing: 0.02
    });
    textMesh.position.set(0, 0, 0.002);
    group.add(textMesh);
  }

  // Scene placement
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // No handlers (static, no interactivity)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geo.dispose();
    mat.dispose();
  };

  return group;
}
